using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "FireIceCreamOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/FireIceCreamOmenData", order = 0)]
public class FireIceCreamOmenData : OnStartOfBattleOmenData
{
	[SerializeField]
	private OmenLogicActionFace afflictionOmenLogicActionFace;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		ReferenceSingleton<SothisOmensHandler>.Instance.FireIceCreamOmenAction = delegate(GameObject target)
		{
			omenInstance.ActivateOmenFeedback();
			afflictionOmenLogicActionFace.ActivateOmen(target);
		};
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<SothisOmensHandler>.Instance.FireIceCreamOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return base.OmenConvertedDescription() + "\n" + Smart.Format(base.localizationManager.GetLocalizedString("FlammableChakram_D"), afflictionOmenLogicActionFace.GetActionDescription().LowercaseFirst());
	}
}
